/**
 * The steam over the mug: a pattern of wisps that tiles vertically, placed in
 * cells from the scene's left edge and top, rising in a loop in the page.
 */
export const nightSceneSteam = {
  column: 136,
  row: 13,
  pattern: [
    " (  ) ",
    "  )  (",
    " (  ) ",
    "  ) ( ",
    " (   )",
    "  )  (",
    " (  ) ",
    "  )   ",
  ] as readonly string[],
} as const

export const nightSceneRows = nightSceneDim.length

/** How many window heights each rain pattern is. */
export const nightSceneRainHeights = 3

/**
 * Rows down to and including the windowsill's edge (row 28). Below it the
 * room fades into dots, which may pass behind the greeting; the sill itself
 * should not, so the scene is sized by these rows rather than all of them.
 */
export const nightSceneSillRows = 29

/** The dotted rows under the sill, which tuck in behind the greeting. */
export const nightSceneFadeRows = nightSceneRows - nightSceneSillRows

/** The size the scene is laid out at; it is then scaled, never re-laid out. */
export const nightSceneLayoutFontPx = 10

/** The smallest and largest type the scene may appear at, in pixels. */
export const nightSceneFontRange = { min: 5, max: 12 } as const

/**
 * How much to scale the scene from its layout size so that, down to its sill,
 * it fills `height`: the way a background image covers its box. The width is
 * never consulted, so a sideways resize never rescales the scene; a scene
 * wider than the workspace is cropped evenly at its sides instead.
 * `naturalHeight` is the scene down to its sill at `nightSceneLayoutFontPx`.
 * The result stays within `nightSceneFontRange`.
 */
export function nightSceneScale(height: number, naturalHeight: number): number {
  if (naturalHeight <= 0) return 1
  const min = nightSceneFontRange.min / nightSceneLayoutFontPx
  const max = nightSceneFontRange.max / nightSceneLayoutFontPx
  return Math.min(max, Math.max(min, height / naturalHeight))
}
